using System.Text.Json;
using DomainConsole.Shared;
namespace DomainConsole;
public sealed class WsusFailedUpdate {public string Id {get;set;}="";public string Title {get;set;}="";public string KB {get;set;}="";}
public sealed partial class RemoteService {
 public Task<string> FailureHistory(TargetRecord target,List<WsusFailedUpdate> failures){var ids=string.Join(",",failures.Select(f=>PowerShellBridge.Literal(f.Id)));var script="$ids=@("+ids+");$search=New-Object -ComObject Microsoft.Update.Searcher;$count=[Math]::Min(500,$search.GetTotalHistoryCount());$items=@();if($count -gt 0){$items=@($search.QueryHistory(0,$count)|Where-Object {$ids -contains [string]$_.UpdateIdentity.UpdateID}|ForEach-Object {@{Id=[string]$_.UpdateIdentity.UpdateID;Title=$_.Title;Date=$_.Date.ToString('o');HResult=[int]$_.HResult;ResultCode=[int]$_.ResultCode;Operation=[int]$_.Operation}})};@{History=@($items);Limit=$count}|ConvertTo-Json -Depth 5 -Compress";
 // A read-only WUA history query can be attempted remotely; access failures are reported as incomplete evidence.
 var cancellation=new CancellationTokenSource(TimeSpan.FromSeconds(30));return HistoryCore(target,script,cancellation);}
 async Task<string> HistoryCore(TargetRecord target,string script,CancellationTokenSource cancellation){using(cancellation)return await PowerShellBridge.Execute(Invoke(target.Host,LiveProbeWrapper(script)),cancellation.Token);}
}
public partial class MainWindow {
 readonly Dictionary<string,DateTimeOffset> failureChecks=new(StringComparer.OrdinalIgnoreCase);
 readonly Dictionary<string,string> wsusFailureDetails=new(StringComparer.OrdinalIgnoreCase);
 async Task ExplainServerFailures(ComputerRow row,WsusReport report){if(report.FailedCount<=0){wsusFailureDetails.Remove(row.Host);return;}if(failureChecks.TryGetValue(row.Host,out var checkedAt)&&DateTimeOffset.UtcNow-checkedAt<TimeSpan.FromMinutes(5))return;failureChecks[row.Host]=DateTimeOffset.UtcNow;var lines=new List<string>{"## Ошибки установки по данным WSUS", "Текущее задание поиска может быть успешно. Серверный статус относится к отдельным обновлениям; время сбоя определяется по клиентской истории."};foreach(var update in report.FailedUpdates)lines.Add(update.Title+" · KB "+update.KB+" · UpdateID "+update.Id+" · WSUS: Failed");if(report.FailureDetailsError.Length>0)lines.Add("Список получен не полностью: "+report.FailureDetailsError);if(report.FailedUpdates.Count==0)lines.Add("WSUS показывает ошибки, но конкретные обновления не получены. Откройте отчёт клиента на WSUS; сброс кэша по одному счётчику не рекомендуется.");else try{var history=await remote.FailureHistory(row.Target,report.FailedUpdates);using var doc=JsonDocument.Parse(history);foreach(var update in report.FailedUpdates){var entries=doc.RootElement.GetProperty("History").EnumerateArray().Where(h=>string.Equals(h.GetProperty("Id").GetString(),update.Id,StringComparison.OrdinalIgnoreCase)&&h.GetProperty("Operation").GetInt32()==1).OrderByDescending(h=>h.GetProperty("Date").GetString()).Take(3).ToList();if(entries.Count==0){lines.Add(update.Title+": соответствующей записи нет в последних 500 событиях истории. После сброса истории она может отсутствовать. Предлагается проверка загрузки и установки / актуальных журналов.");continue;}foreach(var item in entries){int code=item.GetProperty("HResult").GetInt32();int result=item.GetProperty("ResultCode").GetInt32();lines.Add(LocalDateConverter.Format(item.GetProperty("Date").GetString()??"")+" · ResultCode "+result+" · "+ExecutionDiagnosis.Code(code)+" · "+ExecutionDiagnosis.Explain(code));if(code!=0)lines.Add("Рекомендуется: "+ExecutionDiagnosis.Recommend(code));}lines.Add("Код из истории не обязательно относится к текущему заданию. Для детализации соберите журналы вокруг указанного времени; установка заново не запускается.");}}catch(Exception ex){lines.Add("Клиентская история недоступна: "+ex.Message+". Причина пока не установлена; используйте проверку клиента / загрузки и установки.");}wsusFailureDetails[row.Host]=string.Join("\n",lines);if(IsCurrent(row))ShowCurrent();}
}
